import java.util.*;
import java.text.*;
import org.apache.commons.lang.time.DateUtils;

public class Probe2 {
    public static void main(String[] args) throws Exception {
        TimeZone.setDefault(TimeZone.getTimeZone("America/Los_Angeles"));

        // parseDate
        Date d = DateUtils.parseDate("2002-03-28", new String[] {"yyyy-MM-dd"});
        System.out.println("parseDate ok: " + d);
        try {
            DateUtils.parseDate("2002-03-28X", new String[] {"yyyy-MM-dd"});
            System.out.println("NO EXCEPTION (unexpected)");
        } catch (ParseException e) {
            System.out.println("parseDate threw ParseException as expected: " + e.getMessage());
        }

        // modify with huge year -> ArithmeticException
        Calendar huge = Calendar.getInstance();
        huge.set(Calendar.YEAR, 280000001);
        try {
            DateUtils.round(huge, Calendar.HOUR_OF_DAY);
            System.out.println("NO EXCEPTION (unexpected) for huge year round");
        } catch (ArithmeticException e) {
            System.out.println("ArithmeticException as expected: " + e.getMessage());
        }

        // unsupported field -> IllegalArgumentException
        Calendar c = Calendar.getInstance();
        try {
            DateUtils.round(c, Calendar.ZONE_OFFSET);
            System.out.println("NO EXCEPTION (unexpected) for ZONE_OFFSET round");
        } catch (IllegalArgumentException e) {
            System.out.println("IllegalArgumentException as expected: " + e.getMessage());
        }

        // isSameLocalTime quirk: 1 AM vs 1 PM same day
        Calendar amCal = new GregorianCalendar(2002, Calendar.MARCH, 28, 1, 0, 0);
        amCal.set(Calendar.MILLISECOND, 0);
        Calendar pmCal = new GregorianCalendar(2002, Calendar.MARCH, 28, 13, 0, 0);
        pmCal.set(Calendar.MILLISECOND, 0);
        System.out.println("isSameLocalTime(1am,1pm) = " + DateUtils.isSameLocalTime(amCal, pmCal));

        // round(Object) with invalid type
        try {
            DateUtils.round("not a date", Calendar.HOUR_OF_DAY);
            System.out.println("NO EXCEPTION (unexpected) for round(Object) bad type");
        } catch (ClassCastException e) {
            System.out.println("ClassCastException as expected for round(Object): " + e.getMessage());
        }

        // iterator invalid rangeStyle
        try {
            DateUtils.iterator(new Date(), 999);
            System.out.println("NO EXCEPTION (unexpected) for bad rangeStyle");
        } catch (IllegalArgumentException e) {
            System.out.println("IllegalArgumentException as expected for bad rangeStyle: " + e.getMessage());
        }

        // iterator(Object) bad type
        try {
            DateUtils.iterator("not a date", DateUtils.RANGE_WEEK_SUNDAY);
            System.out.println("NO EXCEPTION (unexpected) for iterator(Object) bad type");
        } catch (ClassCastException e) {
            System.out.println("ClassCastException as expected for iterator(Object): " + e.getMessage());
        }

        // DateIterator remove() and exhausted next()
        Iterator it = DateUtils.iterator(new Date(), DateUtils.RANGE_WEEK_SUNDAY);
        try {
            it.remove();
            System.out.println("NO EXCEPTION (unexpected) for iterator remove()");
        } catch (UnsupportedOperationException e) {
            System.out.println("UnsupportedOperationException as expected for remove()");
        }
        while (it.hasNext()) it.next();
        try {
            it.next();
            System.out.println("NO EXCEPTION (unexpected) for exhausted next()");
        } catch (NoSuchElementException e) {
            System.out.println("NoSuchElementException as expected for exhausted next()");
        }

        // add() amount negative
        Date base = new GregorianCalendar(2002, Calendar.MARCH, 28, 13, 45, 1).getTime();
        Date added = DateUtils.addMonths(base, -1);
        Calendar cc = Calendar.getInstance();
        cc.setTime(added);
        System.out.println("addMonths(-1): " + (cc.get(Calendar.MONTH)+1) + "/" + cc.get(Calendar.DAY_OF_MONTH) + "/" + cc.get(Calendar.YEAR));
        System.out.println("original unchanged: " + base);
    }
}
